parameters.responseBody:
{
  "service": "SnackCheck Nutrition Check",
  "description": "Consulta la información nutricional de un alimento mediante su código de barras.",
  "method": "POST",
  "endpoint": "/webhook/nutrition-check",
  "requiredFields": {
    "barcode": "Código de barras numérico, como texto o número"
  },
  "example": {
    "barcode": "3017620422003"
  }
}

{
  "error": "invalid_barcode",
  "message": "Envía un campo 'barcode' que contenga solo dígitos.",
  "example": {
    "barcode": "3017620422003"
  }
}

={{ {
  "error": "product_not_found",
  "barcode": String($('Webhook - Receive Barcode').first().json.body.barcode),
  "message": "No encontramos ese producto en Open Food Facts. Revisa el código o prueba con otro.",
  "example": { "barcode": "3017620422003" }
} }}

={{ {
  "status": "insufficient_data",
  "product": $json.productName,
  "message": "Encontramos el producto, pero no tiene datos de nutrientes suficientes para darte un veredicto confiable."
} }}

parameters.jsCode:
const p = $json;

const concernScore =
  (p.sugarLevel === 'alto' ? 1 : 0) +
  (p.saltLevel === 'alto' ? 1 : 0) +
  (p.fatLevel === 'alto' ? 1 : 0);

return {
  json: {
    ...p,
    concernScore
  }
};
